mapper.select:
select t.res_param,t.res_param resParam,t.log_cmd,t.log_cmd logCmd,t.machine_id,t.machine_id
machineId,t.staff_name,t.staff_name staffName,t.log_id,t.log_id logId,t.req_param,t.req_param
reqParam,t.state,t.store_id,t.store_id storeId,t.log_action,t.log_action logAction,t.staff_id,t.staff_id staffId,
t.create_time createTime
from work_license_log t
where 1 =1

    and t.res_param= #{resParam}


    and t.log_cmd= #{logCmd}


    and t.machine_id= #{machineId}


    and t.staff_name= #{staffName}


    and t.log_id= #{logId}


    and t.req_param= #{reqParam}


    and t.state= #{state}


    and t.store_id= #{storeId}


    and t.log_action= #{logAction}


    and t.staff_id= #{staffId}

order by t.create_time desc

    limit #{page}, #{row}

